Verification script template (from the itr#487 close; original lived in a session scratchpad). Adapt into a Playwright spec on the daemon-server fixture:

// Runtime verification for itr#487: mobile two-step terminal workflow.
// Drives the live isolated server on :3199 at an iPhone-ish viewport.
import { createRequire } from 'node:module'
const require = createRequire('/Users/josefaguilar/AI_Projects/wisphive/crates/wisphive_web/frontend/package.json')
const { chromium, devices } = require('@playwright/test')

const OUT = '/private/tmp/claude-501/-Users-josefaguilar-AI-Projects-wisphive/c461069c-6cbd-4c2b-8937-607cecb27255/scratchpad'
const BASE = 'https://localhost:3199'
const PASSWORD = 'wisphive-mobile-check-pw'

const browser = await chromium.launch()
const ctx = await browser.newContext({
  ...devices['iPhone 13'],
  ignoreHTTPSErrors: true,
})
const page = await ctx.newPage()

// Answer the "+ New terminal" label prompt() when it fires.
page.on('dialog', (d) => d.accept('mobile-check'))

await page.goto(`${BASE}/`)

// First-run onboarding OR returning login (password persists in the HOME).
const welcome = page.getByText('Welcome. Set a password to finish setup.')
const passwordField = page.getByLabel('Password', { exact: true })
await welcome.or(passwordField).first().waitFor({ timeout: 15000 })
if (await welcome.isVisible()) {
  await page.getByLabel('New password').fill(PASSWORD)
  await page.getByLabel('Confirm password').fill(PASSWORD)
  await page.getByRole('button', { name: 'Set password' }).click()
} else {
  await passwordField.fill(PASSWORD)
  await page.getByRole('button', { name: 'Sign in', exact: true }).click()
}
const skipEnroll = page.getByRole('button', { name: 'Skip for now' })
const inbox = page.locator('.inbox')
await skipEnroll.or(inbox).first().waitFor({ timeout: 15000 })
if (await skipEnroll.isVisible()) await skipEnroll.click()

// → Terminals view.
await page.getByRole('button', { name: /^Terminals/ }).click()
await page.locator('.terminals-layout').waitFor()

// Create a session, wait for it to land in the list.
await page.getByRole('button', { name: '+ New terminal' }).click()
await page.locator('.terminals-sidebar-item').first().waitFor({ timeout: 15000 })
await page.screenshot({ path: `${OUT}/step1-mobile-list.png` })

// Assert action 1: list-only (main pane hidden).
const mainHiddenBefore = await page.locator('.terminals-main').isHidden()

// Action 2: tap the session → full-screen sub-window.
await page.locator('.terminals-sidebar-item').first().tap()
await page.locator('.terminals-mobile-header').waitFor({ timeout: 15000 })
await page.locator('.xterm-viewport').waitFor({ timeout: 15000 })
await page.waitForTimeout(700) // let the PTY paint a shell prompt
await page.screenshot({ path: `${OUT}/step2-mobile-subwindow.png` })
const sidebarHiddenOpen = await page.locator('.terminals-sidebar').isHidden()
const mainBox = await page.locator('.terminals-main').boundingBox()

// Back → list again.
await page.getByRole('button', { name: 'Back to terminal list' }).tap()
await page.waitForTimeout(200)
await page.screenshot({ path: `${OUT}/step3-mobile-back-to-list.png` })
const mainHiddenAfter = await page.locator('.terminals-main').isHidden()
const rootFlags = await page.evaluate(() => ({
  isMobileVar: getComputedStyle(document.documentElement).getPropertyValue('--is-mobile').trim(),
  viewport: document.documentElement.dataset.viewport,
}))

// Desktop regression probe: widen past the breakpoint with the session open.
await page.setViewportSize({ width: 1400, height: 900 })
await page.locator('.terminals-sidebar-item').first().click()
await page.waitForTimeout(700)
await page.screenshot({ path: `${OUT}/step4-desktop-side-by-side.png` })
const desktop = await page.evaluate(() => ({
  sidebarVisible: !!document.querySelector('.terminals-sidebar')?.checkVisibility(),
  headerHidden: !document.querySelector('.terminals-mobile-header')?.checkVisibility(),
  isMobileVar: getComputedStyle(document.documentElement).getPropertyValue('--is-mobile').trim(),
  viewport: document.documentElement.dataset.viewport,
}))

console.log(JSON.stringify({
  mainHiddenBefore, sidebarHiddenOpen, mainBox, mainHiddenAfter, rootFlagsMobile: rootFlags, desktop,
}, null, 2))

await browser.close()

